import{_ as a,c as s,o as n,ag as t}from"./chunks/framework.B3RpK1bM.js";const u=JSON.parse('{"title":"Grammar Design","description":"","frontmatter":{},"headers":[],"relativePath":"en_EN/syntax-design.md","filePath":"en_EN/syntax-design.md","lastUpdated":1769658044000}'),o={name:"en_EN/syntax-design.md"};function i(p,e,l,r,c,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="grammar-design" tabindex="-1">Grammar Design <a class="header-anchor" href="#grammar-design" aria-label="Permalink to &quot;Grammar Design&quot;">​</a></h1><p><a href="./">Return to Table of Contents</a></p><p>To make it easier for playwrighting and performance design, grammar design has separated the script from performances. Below is an explanation for both scripts and performances:</p><h2 id="script" tabindex="-1">Script <a class="header-anchor" href="#script" aria-label="Permalink to &quot;Script&quot;">​</a></h2><h3 id="dialogue-box" tabindex="-1">Dialogue Box <a class="header-anchor" href="#dialogue-box" aria-label="Permalink to &quot;Dialogue Box&quot;">​</a></h3><p>The dialogue can be displayed using <code>Dialogue Box</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Dialogue]</span></span>
<span class="line"><span>This is how dialogue is displayed using a dialogue box.</span></span>
<span class="line"><span>Miss: This is Miss&#39;s speaking style when in a dialogue box.</span></span></code></pre></div><h3 id="full-screen" tabindex="-1">Full Screen <a class="header-anchor" href="#full-screen" aria-label="Permalink to &quot;Full Screen&quot;">​</a></h3><p>Also, you can use <code>Fullscreen</code> to display:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Fullscreen]</span></span>
<span class="line"><span>Supports displaying multiple pieces of content but does not support by roles speaking. It supports saying up to 12 lines at once while in full screen mode.</span></span>
<span class="line"><span>[Fullscreen]</span></span>
<span class="line"><span>We can also redefine this so that we can switch between line numbers earlier on.</span></span></code></pre></div><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>Options are displayed in the same way as dialogue boxes and full screens, however, they will store the contents of options and allow players to choose them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Options]</span></span>
<span class="line"><span>{script: test3.txt} Jump to Test3</span></span>
<span class="line"><span>{jump: loop1}</span></span>
<span class="line"><span>Continue</span></span>
<span class="line"><span>[Fullscreen]</span></span>
<span class="line"><span>After selecting fullscreen, you can see this text.</span></span></code></pre></div><h3 id="professional-terms" tabindex="-1">Professional Terms <a class="header-anchor" href="#professional-terms" aria-label="Permalink to &quot;Professional Terms&quot;">​</a></h3><p>Script support BBCode syntax, and we can define some professional terms using the following method:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Fullscreen]</span></span>
<span class="line"><span>This is a [link=https://www.example.com/professional-term]professional term[/link].</span></span></code></pre></div><p>Selecting a professional term will open a dictionary frame where you can define the professional term in the <code>professional_terms.txt</code> file under the <code>dictionary</code> folder, allowing us to set professional terms.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="goto-mark-position" tabindex="-1">Goto Mark Position <a class="header-anchor" href="#goto-mark-position" aria-label="Permalink to &quot;Goto Mark Position&quot;">​</a></h3><p>When there is a need to backtrack to a specific scene in the script due to a required transition, you can set the <strong>mark position</strong> using the <code>@</code> symbol. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@loop1</span></span>
<span class="line"><span>Here is a dead loop</span></span>
<span class="line"><span>{jump: loop1}</span></span></code></pre></div><p>When jumping back, it returns to the position marked with <code>@loop1</code>. Apart from setting mark positions, all other performance methods are managed using braces. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{background: cover.png} # Switches background</span></span>
<span class="line"><span>{girl: normal.png - 1200x650 - 1.1} Girl: Hello everyone # Sets portrait</span></span>
<span class="line"><span>{script: test2.txt, jump: loop1} # Jumps to the loop1 location in the test2 script</span></span></code></pre></div><h3 id="independent-performance" tabindex="-1">Independent Performance <a class="header-anchor" href="#independent-performance" aria-label="Permalink to &quot;Independent Performance&quot;">​</a></h3><p>Generally, performances rely on the text</p>`,25)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
